--
-- Structure de la table `codifications`
--

DROP TABLE IF EXISTS `codifications`;
CREATE TABLE IF NOT EXISTS `codifications` (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `dossier` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `code_dossier` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
