  UNIQUE KEY `codifications_code_dossier_unique` (`code_dossier`)
) ENGINE=MyISAM AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

