--
-- Structure de la table `consigne_groupes`
--

DROP TABLE IF EXISTS `consigne_groupes`;
CREATE TABLE IF NOT EXISTS `consigne_groupes` (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
